#!/usr/bin/env bash
# Phase 1 독립 분석: Antigravity(시각, 인터랙션, 애니메이션 책임자). 저장소 루트에서 실행.
cd "$(dirname "$0")/../.." || exit 1
COMMON='First read migration-audit/BRIEF.md, then migration-audit/MISSION.md sections 2 (your role: AGY), 3, 4, 5 and 7, then DESIGN.md. You are the visual, interaction and animation lead of this audit. This run is Phase 1, independent analysis. Rules: do not modify any file under web/ or any existing document; do not run git commands that change anything; do not run next build; do not read other files in migration-audit/analysis (other participants work independently). You may create files only under the folders named below. Never claim to have seen or run something you did not. Separate four kinds of statements: seen on screen, read in code, ran myself (with the command), guess. Write in Korean, no em dash characters, no middle dot characters, no exclamation marks. Give file paths and line numbers. Use ids with the prefix AG- (for example AG-U-001, AG-A-001, AG-I-001).'
run() {
  rtk agy --dangerously-skip-permissions --model gemini-3.8-flash-high --effort high --print "$COMMON $2" > "migration-audit/logs/agy-$1-run.log" 2>&1
  echo "done $1 exit $?"
}
run a "TASK A, source analysis. Write one file: migration-audit/analysis/agy-a-visual-source.md. From the code only (web/app/*.css, web/app/ui.css, web/tailwind.config.ts, web/components, web/lib/opening*.ts, web/components/box/Opening.tsx and Reveal.tsx, web/components/home/HeroBanner.tsx and heroBall.ts, framer-motion usages, canvas-confetti usages, opening/STATE.md) produce: (1) the design tokens actually defined (colors, type scale, radii, spacing, breakpoints, z-index layers, shadows, motion durations and easings) with where each is defined; (2) the fonts actually loaded and how; (3) an animation inventory: every animation and transition with trigger, duration, delay, easing, keyframes or spring parameters, properties animated, stagger, loop, exit, what happens on interruption or unmount, reduced-motion behaviour, sound or haptics, completion callback and what that callback changes; (4) the box opening sequence as a timeline from the press of the open button to the state where the next opening is possible, for single and multi opening, with the exact timings from code and which step commits money and inventory (is any ledger change tied to an animation end event?); (5) every hover, focus-visible, active, disabled, selected, loading and error style defined for interactive elements, per component class; (6) every modal, sheet, drawer, popover, tooltip, toast, dropdown, accordion, tab, skeleton, empty state and error state that exists in code, how it opens and closes (escape, outside click, back button), scroll lock and focus trap; (7) responsive rules: every media query and container rule and what changes; (8) text that can wrap or truncate differently per language (ko, en, zh) based on the message files web/messages/v.*.json and fixed widths in CSS. End with the ten things most likely to differ between two builds of this app that a pixel comparison must control for (time-dependent text, random seeds, animation frames, lazy images, fonts)." &
run b "TASK B, real browser analysis of the deployed reference site https://shinwon446-eng.github.io/voila-test-aresjoo/ko/ (also /en/ and /zh/). Playwright is installed in web/node_modules (see the existing scripts in web/scripts/capture for how they launch Chrome with channel chrome, seed localStorage state with states.mjs, and take CAPTURE_BASE). Write your own scripts under migration-audit/harness/agy/ and save screenshots under migration-audit/screenshots/before/agy/. Everything on that site is a browser-only test ledger with fake money, but still do not submit any withdrawal or shipping form. Write one report: migration-audit/analysis/agy-b-visual-browser.md. Do: (1) capture every route listed in BRIEF section 0 at widths 320, 390, 768, 1280 and 1920 in ko, and at 390 and 1440 in en and zh, first screen and full page; for the box route use slugs gaming-playstation, watch-rolex and pokemon-charizard; (2) for each capture record document width versus window width (horizontal overflow), console errors, failed requests and missing images; (3) extract computed styles in the browser for the main primitives (primary button, quiet button, link, chip, card, input, sheet, header, footer, box card, item row): font family actually used, font size, weight, line height, letter spacing, padding, gap, radius, border, background, color, shadow, and compare them with the tokens in web/app/ui.css; (4) open every sheet and overlay you can reach without an account (menu, login, charge, balance, verify, item detail, odds table, language and currency) and capture open state, then check escape, outside click and scroll lock; (5) capture hover and focus-visible states for the primitives at 1280; (6) record the opening animation as a frame sequence: use an existing seeded state from web/scripts/capture/states.mjs with CAPTURE_BASE pointing at the deployed site, open one box and five boxes, capture frames every 100 ms from press to result, and report the measured duration of each phase, both normal and with reduced motion; (7) list every place where text wraps, truncates or overflows differently in en or zh compared with ko. In the report, link each finding to the screenshot file. If something could not be run, say exactly what and why." &
wait
